function monday(d){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parse(s){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dateLabel(s,weekday=true){return new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',...(weekday?{weekday:'short'}:{})}).format(parse(s))}
function weekEnd(){return addDays(state.week,6)}
function weekSessions(){const a=iso(state.week),b=iso(weekEnd());return state.sessions.filter(x=>x.session_date>=a&&x.session_date<=b)}
function flash(msg){let el=document.querySelector('.sp-toast');if(!el){el=document.createElement('div');el.className='sp-toast hidden';root.append(el)}el.textContent=msg;el.classList.remove('hidden');clearTimeout(flash.t);flash.t=setTimeout(()=>el.classList.add('hidden'),2800)}

async function start(){
  if(!SUPABASE_URL||!SUPABASE_PUBLISHABLE_KEY){login('supabase-config.js의 URL과 publishable key를 확인해 주세요.');return}
  db.auth.onAuthStateChange((event,next)=>{
    state.user=next?.user||null;
    if(event==='PASSWORD_RECOVERY'){passwordRecovery=true;renderPasswordRecovery();return}
    if(passwordRecovery)return;
    if(state.user)load();else login();
  });
  const {data:{session},error}=await db.auth.getSession();if(error){login(error.message);return}
  if(passwordRecovery)return;
  state.user=session?.user||state.user;
  if(state.user)await load();else login();
}
function login(message='',mode=authMode){
  authMode=mode;
  const reset=mode==='reset',signup=mode==='signup';
  const title=reset?'비밀번호 설정':signup?'계정 만들기':'로그인';
  const description=reset?'계정 이메일로 비밀번호 설정 링크를 보내드려요. 기존 이메일 로그인 계정도 여기서 비밀번호를 만들 수 있어요.':signup?'이메일과 비밀번호를 등록하면 다른 기기에서도 같은 기록을 볼 수 있어요.':'이메일과 비밀번호로 로그인하세요.';
  const button=reset?'설정 링크 보내기':signup?'계정 만들기':'로그인';
  root.innerHTML=`<section class="sp-card sp-login"><div class="sp-brand"><span class="sp-mark">✓</span>개인 투자 공부</div><h1>${title}</h1><p>${description}</p><form id="sp-login"><input class="sp-input" type="email" name="email" autocomplete="email" placeholder="이메일 주소" required>${reset?'':`<input class="sp-input" type="password" name="password" autocomplete="${signup?'new-password':'current-password'}" minlength="8" placeholder="비밀번호 (8자 이상)" required>`}<button class="sp-btn primary" type="submit">${button}</button></form><div class="sp-login-links">${reset?'<button class="sp-link" type="button" data-auth-mode="signin">로그인으로 돌아가기</button>':signup?'<button class="sp-link" type="button" data-auth-mode="signin">이미 계정이 있어요</button>':'<button class="sp-link" type="button" data-auth-mode="signup">처음 사용하시나요? 계정 만들기</button><button class="sp-link" type="button" data-auth-mode="reset">비밀번호 설정 / 재설정</button>'}</div>${message?`<div class="sp-errors">${esc(message)}</div>`:''}</section>`;
}
function renderPasswordRecovery(message=''){
  root.innerHTML=`<section class="sp-card sp-login"><div class="sp-brand"><span class="sp-mark">✓</span>개인 투자 공부</div><h1>새 비밀번호 설정</h1><p>새 비밀번호를 입력해 주세요.</p><form id="sp-password-recovery"><input class="sp-input" type="password" name="password" autocomplete="new-password" minlength="8" placeholder="새 비밀번호 (8자 이상)" required><input class="sp-input" type="password" name="confirmPassword" autocomplete="new-password" minlength="8" placeholder="새 비밀번호 확인" required><button class="sp-btn primary" type="submit">비밀번호 저장</button></form>${message?`<div class="sp-errors">${esc(message)}</div>`:''}</section>`;
}
async function load(){
  const uid=state.user.id;
  const results=await Promise.all([
    db.from('study_sessions').select('*').order('session_date'),
    db.from('study_records').select('*').order('record_date',{ascending:false}).order('created_at',{ascending:false}),
    db.from('study_questions').select('*').order('due_on'),
    db.from('study_inbox').select('*').order('saved_on',{ascending:false}),
    db.from('study_companies').select('*').order('created_at',{ascending:false}),
    db.from('study_settings').select('*').eq('user_id',uid).maybeSingle()
  ]);
    const err=results.find(r=>r.error)?.error;
  if(err){root.innerHTML=`<section class="sp-card sp-login"><h2>데이터베이스 설정이 필요해요</h2><p>Supabase SQL Editor에서 <code>supabase/studyplan_schema.sql</code>을 실행한 뒤 새로고침해 주세요.</p><small>${esc(err.message)}</small></section>`;return}
  [state.sessions,state.records,state.questions,state.inbox,state.companies]=results.slice(0,5).map(r=>r.data||[]);
  state.settings=results[5].data;
  if(!state.settings){const {data,error}=await db.from('study_settings').upsert({user_id:uid},{onConflict:'user_id'}).select().single();if(error){root.innerHTML=`<p class="sp-errors">${esc(error.message)}</p>`;return}state.settings=data}
  render();
}
function primaryTab(id=state.tab){if(['home','plan','weekly_plan','weekly_review','trial_review'].includes(id))return 'home';if(['learningpractice','questions','mentoring','companies','company_research','dcf_review','judgment_review'].includes(id))return 'learningpractice';return 'inbox'}
function render(){if(!state.user){login();return}const focusing=!!state.focusId,finishing=!!state.finishId,active=primaryTab(),pageTitle=MORE_TABS.find(([id])=>id===state.tab)?.[1]||({questions:'질문과 복습',mentoring:'멘토링 기록',companies:'기업 분석',inbox:'자료함'}[state.tab])||RECORD_TITLES[state.tab]||TABS.find(([id])=>id===active)?.[1];root.innerHTML=`<main class="sp ${focusing?'sp-focused':''} ${state.tab==='home'?'sp-home':''}"><header class="sp-top"><div class="sp-brand"><span class="sp-mark">✓</span><span>개인 투자 공부</span></div>${focusing||finishing?`<button class="sp-btn" data-act="return-home">← 오늘 화면으로 돌아가기</button>`:`<div class="sp-actions"><span class="sp-user">${esc(state.user.email)}</span><button class="sp-btn sm" data-act="change-password">비밀번호 설정</button><button class="sp-btn sm" data-act="backup">백업</button><button class="sp-btn sm" data-act="logout">로그아웃</button></div>`}</header>${focusing?focusView():finishing?finishView():`<section class="sp-hero"><div><div class="sp-eyebrow">${active==='home'?(state.tab==='home'?'오늘 공부':'주간 계획 조정'):active==='learningpractice'?(state.tab==='learningpractice'?'배우기 · 설명하기 · 분석하기 · 복기하기':'학습 · 실전 기록'):'읽을거리와 참고자료를 연결해요'}</div><h1>${pageTitle}</h1><p>${dateLabel(iso(new Date()))}${active==='home'?' · 오늘 할 작업을 모아두었어요.':''}</p></div>${state.tab==='plan'?`<div class="sp-nav"><button class="sp-btn" data-act="prev" aria-label="이전 주">‹</button><span class="range">${dateLabel(iso(state.week),false)} – ${dateLabel(iso(weekEnd()),false)}</span><button class="sp-btn" data-act="next" aria-label="다음 주">›</button><button class="sp-btn sm" data-act="today">이번 주</button></div>`:''}</section><nav class="sp-tabs" aria-label="주요 메뉴">${TABS.map(([id,name])=>`<button class="${active===id?'active':''}" data-tab="${id}">${name}</button>`).join('')}</nav>${state.tab==='home'?home():state.tab==='learningpractice'?learningPracticeHome():state.tab==='plan'?plan():state.tab==='questions'?questionsView():state.tab==='inbox'?inboxView():state.tab==='companies'?companiesView():recordView(state.tab)}<footer class="sp-footer"><span>개인 기록은 Supabase 계정에 저장됩니다.</span><span>시험 운영 ${trialLabel()}</span></footer>`}${state.modal?modalHtml():''}</main><div class="sp-toast hidden"></div>`}
function trialLabel(){const start=parse(state.settings?.trial_started_on||iso(new Date())),days=Math.floor((new Date(iso(new Date()))-start)/86400000);return days<14?`${Math.max(0,14-days)}일 남음`:'2주 점검 가능'}
function stat(title,val,note){return `<div class="sp-stat"><label>${title}</label><strong>${val}</strong><small>${note}</small></div>`}
function hour(n){return `${Math.round(n/6)/10}시간`}
function sessionOrderKey(date=state.viewDate){return `study-session-order:${state.user?.id||'local'}:${date||iso(new Date())}`}
function legacySessionOrderKey(){return `study-session-order:${state.user?.id||'local'}`}
function orderedDateRows(rows,date){let order=[];try{order=JSON.parse(localStorage.getItem(sessionOrderKey(date))||'[]')}catch{}if(!order.length&&date===iso(new Date()))try{order=JSON.parse(localStorage.getItem(legacySessionOrderKey())||'[]')}catch{}return rows.slice().sort((a,b)=>{const ai=order.indexOf(a.id),bi=order.indexOf(b.id);if(ai>=0||bi>=0)return (ai<0?999:ai)-(bi<0?999:bi);return sortSessions(a,b)})}
function isNonStudyBlock(s){return ['rest','buffer'].includes(s.details?.block_kind)||s.category==='break'}
function studyMinutes(rows){return rows.filter(s=>!isNonStudyBlock(s)).reduce((n,s)=>n+Number(s.planned_minutes||0),0)}
function scheduledMinutes(rows){return rows.reduce((n,s)=>n+Number(s.planned_minutes||0),0)}
function availabilityKey(){return `study-daily-availability:${state.user?.id||'local'}`}
function availabilityMap(){try{return JSON.parse(localStorage.getItem(availabilityKey())||'{}')}catch{return {}}}
function focusDraftKey(id){return `study-focus-draft:${state.user?.id||'local'}:${id}`}
function readFocusDraft(id){try{return JSON.parse(localStorage.getItem(focusDraftKey(id))||'null')}catch{return null}}
function defaultAvailability(date){const day=parse(date).getDay();return day===0||day===6?240:30}
function availableMinutes(date){const map=availabilityMap();return Number.isFinite(Number(map[date]))?Number(map[date]):defaultAvailability(date)}
function sessionKind(s){return s.details?.block_kind==='buffer'?'예비시간':s.details?.block_kind==='rest'||s.category==='break'?'휴식':CATEGORIES[s.category]||'공부'}
function progressLabel(s){return ({planned:'예정',done:'완료',partial:'일부 진행',skipped:'건너뜀'})[s.status]||'예정'}
function dayRowsFor(date){return orderedDateRows(state.sessions.filter(s=>s.session_date===date),date)}
function home(){const date=state.viewDate||iso(new Date()),selected=parse(date),weekStart=state.homeMode==='week'?state.week:monday(selected),weekEndDate=addDays(weekStart,6);if(state.homeMode==='day')state.week=weekStart;const rows=dayRowsFor(date),lastId=localStorage.getItem(`study-last-session:${state.user.id}`),resume=state.sessions.find(s=>s.id===lastId&&!['done','skipped'].includes(s.status)),first=resume?.session_date===date?resume:rows.find(s=>!['done','skipped'].includes(s.status)&&!isNonStudyBlock(s)),due=state.questions.filter(q=>!q.completed_at&&q.due_on<=date),focusCompany=state.companies.find(c=>c.is_primary&&c.status==='active'),reading=state.inbox.find(i=>!i.processed&&i.source_url&&['now','this_week'].includes(i.queue)),available=availableMinutes(date),planned=studyMinutes(rows),over=planned>available;return `<section class="sp-home-controls"><div class="sp-home-date"><div><div class="sp-eyebrow">${date===iso(new Date())?'오늘의 계획':'선택한 날짜'}</div><label class="sp-date-control"><span class="sr-only">계획 날짜</span><input type="date" id="home-date" value="${date}" aria-label="계획 날짜"><button class="sp-btn sm" data-act="today-date">오늘로</button></label></div><div class="sp-plan-switch" role="tablist" aria-label="계획 보기"><button class="${state.homeMode==='day'?'active':''}" role="tab" aria-selected="${state.homeMode==='day'}" data-act="home-day">일일계획</button><button class="${state.homeMode==='week'?'active':''}" role="tab" aria-selected="${state.homeMode==='week'}" data-act="home-week">주간계획</button></div></div>${state.homeMode==='week'?`<div class="sp-week-controls"><button class="sp-btn sm" data-act="prev">‹ 이전 주</button><strong>${dateLabel(iso(weekStart),false)} – ${dateLabel(iso(weekEndDate),false)}</strong><button class="sp-btn sm" data-act="next">다음 주 ›</button></div>`:''}</section>${state.homeMode==='week'?weekHome(weekStart):dayHome({date,rows,first,resume,available,planned,over,due,focusCompany,reading})}<details class="sp-home-options"><summary>주간 메모와 점검</summary><div class="sp-option-links">${MORE_TABS.map(([id,name])=>`<button class="sp-btn sm" data-tab="${id}">${name}</button>`).join('')}</div></details><details class="sp-metrics"><summary>이번 주 공부 기록</summary>${weekMetrics(weekSessions())}</details>`}
function dayHome({date,rows,first,resume,available,planned,over,due,focusCompany,reading}){const hasOtherResume=resume&&resume.session_date!==date,firstContext=first?(first.details?.linked_inbox_title||first.details?.linked_target||focusCompany?.name||first.details?.source_location||'연결 자료 또는 학습 기록을 확인하세요.'):'';return `<div class="sp-day-home"><div class="sp-day-main"><section class="sp-availability ${over?'over':''}"><div><strong>${date===iso(new Date())?'오늘':'선택한 날'} 가능한 시간</strong><span>${planned}분 예정 · ${available}분 가용${over?' · 가용 시간 초과':''}</span></div><button class="sp-link" data-act="edit-availability">수정</button>${state.editAvailability?`<div class="sp-availability-edit"><label for="availability-value">${dateLabel(date)} 가용 시간 (분)</label><input id="availability-value" class="sp-input" type="number" min="0" max="1440" step="5" value="${state.availabilityValue??available}"><button class="sp-btn primary sm" data-act="save-availability" data-date="${date}">저장</button><button class="sp-link" data-act="cancel-availability">취소</button></div>`:''}</section><section class="sp-first-task"><div class="sp-first-task-heading"><span class="sp-eyebrow">${first?(first.id===resume?.id?'이어서 할 작업':'오늘 첫 작업'):'오늘 첫 작업'}</span>${first?`<span>${sessionKind(first)} · ${first.planned_minutes}분</span>`:''}</div>${first?`<div class="sp-first-task-body"><div><h2>${esc(first.title)}</h2><p class="sp-first-context">${esc(firstContext)}</p>${first.next_step?`<p class="sp-first-next"><strong>다음 행동</strong> ${esc(first.next_step)}</p>`:''}</div><button class="sp-btn primary sp-start" data-act="start-session" data-id="${first.id}">${first.id===resume?.id?'이어서':'시작'}</button></div>`:`<div class="sp-first-task-body"><p>이 날짜에는 아직 일정이 없습니다.</p><button class="sp-btn primary" data-act="add-session">일정 추가</button></div>`}</section><section class="sp-day-schedule"><div class="sp-day-section-heading"><h2>${date===iso(new Date())?'오늘':'선택한 날'}의 전체 일정</h2><span>${rows.length}개 · ${scheduledMinutes(rows)}분 배정</span></div><div class="sp-day-rows">${rows.length?rows.map((s,i)=>daySessionRow(s,i,rows.length,date)).join(''):'<p class="sp-day-empty">일정이 없습니다.</p>'}</div><button class="sp-btn sm sp-add-session" data-act="add-session">＋ 일정 추가</button></section></div><aside class="sp-day-aside"><details><summary>복습 질문 ${due.length?`· ${due.length}개`:''}</summary><div class="sp-support-body">${due.slice(0,2).map(q=>`<p>${esc(q.question)} <button class="sp-link" data-act="review-question" data-id="${q.id}">회상</button></p>`).join('')||'<p class="sp-muted">오늘 복습할 질문이 없습니다.</p>'}</div></details><details><summary>실전 분석${focusCompany?` · ${esc(focusCompany.name)}`:''}</summary><div class="sp-support-body">${focusCompany?`<p>${esc(focusCompany.next_action||focusCompany.core_question||'다음 확인 사항을 기록하세요.')}</p>`:'<p class="sp-muted">진행 중인 분석이 없습니다.</p>'}<button class="sp-link" data-tab="companies">분석 열기</button></div></details><details><summary>이번 주 읽을거리${reading?` · ${esc(reading.title)}`:''}</summary><div class="sp-support-body">${reading?`<p>${esc(reading.reason||'')}</p><a class="sp-btn sm" href="${esc(reading.source_url)}" target="_blank" rel="noopener">원문 열기 ↗</a>`:'<p class="sp-muted">선택된 자료가 없습니다.</p>'}<button class="sp-link" data-tab="inbox">자료함</button></div></details>${hasOtherResume?`<section class="sp-resume-elsewhere"><strong>이어서 할 작업</strong><p>${esc(resume.title)} · ${dateLabel(resume.session_date)}</p><p>${esc(resume.next_step||'다음 행동을 아직 정하지 않았어요.')}</p><button class="sp-btn sm" data-act="start-session" data-id="${resume.id}">이어서</button></section>`:''}</aside></div>`}
function daySessionRow(s,index,count,date){const nonStudy=isNonStudyBlock(s),isFirst=s.id===dayRowsFor(date).find(x=>!['done','skipped'].includes(x.status)&&!isNonStudyBlock(x))?.id;return `<article class="sp-day-row ${isFirst?'is-first':''} ${nonStudy?'non-study':''}"><span class="sp-order">${index+1}</span><div class="sp-day-task-main"><div class="sp-day-task-title">${esc(s.title)}</div><div class="sp-day-task-meta"><span>${sessionKind(s)} · ${s.planned_minutes}분</span><span>${progressLabel(s)}</span></div><details class="sp-row-detail"><summary>공부 순서 · 완료 기준</summary><div>${s.details?.study_steps?`<p><strong>순서</strong> ${esc(s.details.study_steps)}</p>`:''}${s.details?.completion_criteria||s.details?.output?`<p><strong>완료 기준</strong> ${esc(s.details.completion_criteria||s.details.output)}</p>`:''}${s.details?.linked_target?`<p><strong>연결 대상</strong> ${esc(s.details.linked_target)}</p>`:''}${s.details?.avoid?`<p><strong>유의</strong> ${esc(s.details.avoid)}</p>`:''}${!s.details?.study_steps&&!s.details?.completion_criteria&&!s.details?.output&&!s.details?.linked_target?'<p class="sp-muted">상세 내용이 아직 없어요.</p>':''}</div></details></div><div class="sp-day-actions">${!nonStudy&&!['done','skipped'].includes(s.status)?`<button class="sp-link" data-act="start-session" data-id="${s.id}">시작</button>`:''}<button class="sp-link" data-act="edit-session" data-id="${s.id}">수정</button>${!nonStudy&&s.status!=='done'?`<button class="sp-link" data-act="move-session" data-id="${s.id}">이동</button>`:''}<span class="sp-order-actions"><button class="sp-link" aria-label="${esc(s.title)} 위로" data-act="order-up" data-date="${date}" data-id="${s.id}" ${index===0?'disabled':''}>↑</button><button class="sp-link" aria-label="${esc(s.title)} 아래로" data-act="order-down" data-date="${date}" data-id="${s.id}" ${index===count-1?'disabled':''}>↓</button></span></div></article>`}
function weekHome(weekStart){const days=Array.from({length:7},(_,i)=>{const date=iso(addDays(weekStart,i)),rows=dayRowsFor(date);return {date,rows,available:availableMinutes(date)}}),weeklyBooked=days.reduce((n,d)=>n+scheduledMinutes(d.rows),0),weeklyStudy=days.reduce((n,d)=>n+studyMinutes(d.rows),0);return `<section class="sp-week-summary"><span>주간 배정 <strong>${weeklyBooked}분</strong></span><span>공부 <strong>${weeklyStudy}분</strong></span><span>휴식·예비는 공부시간에서 제외</span></section><div class="sp-week-grid">${days.map(({date,rows,available})=>{const over=studyMinutes(rows)>available;return `<section class="sp-week-day ${date===iso(new Date())?'is-today':''}"><button class="sp-week-day-head" data-act="select-date" data-date="${date}"><span>${DAY_NAMES[parse(date).getDay()]}</span><strong>${dateLabel(date,false)}</strong><small>${studyMinutes(rows)} / ${available}분 공부${over?' · 초과':''}</small></button><div class="sp-week-day-items">${rows.length?rows.map(s=>`<button class="sp-week-item ${s.details?.block_kind==='rest'||s.category==='break'?'non-study':''}" data-act="select-date" data-date="${date}" title="${esc(s.title)}"><span>${esc(s.title)}</span><small>${s.planned_minutes}분 · ${progressLabel(s)}</small></button>`).join(''):'<span class="sp-week-empty">일정 없음</span>'}</div></section>`}).join('')}</div><div class="sp-week-links"><button class="sp-btn sm" data-tab="plan">주간 시간표 상세</button><button class="sp-btn sm" data-tab="weekly_plan">주간 계획 메모</button><button class="sp-btn sm" data-tab="weekly_review">주간 점검</button><button class="sp-btn sm" data-tab="trial_review">2주 점검</button></div>`}
function weekMetrics(rows){const study=studyMinutes(rows),done=rows.filter(s=>!isNonStudyBlock(s)&&s.status==='done').length,total=rows.filter(s=>!isNonStudyBlock(s)&&s.status!=='skipped').length,pct=total?Math.round(done/total*100):0;return `<section class="sp-stats">${stat('이번 주 공부 블록',total,'휴식·예비 제외')}${stat('완료 블록',done,'표시된 공부 작업')}${stat('실제 공부 시간',hour(rows.filter(s=>!isNonStudyBlock(s)).reduce((n,s)=>n+Number(s.actual_minutes||0),0)),'실제 시간만')}${stat('완료율',`${pct}%`,'휴식·예비 제외')}</section><section class="sp-card"><div class="sp-card-head"><h2>주간 공부 시간</h2></div><div class="sp-card-body"><div class="sp-chart">${weekChart(rows.filter(s=>!isNonStudyBlock(s)))}</div><p class="sp-muted">전체 배정 ${hour(scheduledMinutes(rows))} · 공부 ${hour(study)} · 휴식·예비 ${hour(scheduledMinutes(rows)-study)}</p></div></section>`}
function learningPracticeHome(){const questions=state.questions.filter(q=>!q.completed_at),mentoring=state.records.filter(r=>r.record_type==='mentoring').slice(0,1),company=state.companies.find(c=>c.is_primary&&c.status==='active'),records=state.records.filter(r=>['company_research','dcf_review','judgment_review'].includes(r.record_type));return `<section class="sp-hub-intro"><h2>배우고, 적용하고, 돌아보기</h2><p>멘토링과 복습에서 익힌 내용을 기업 분석과 내 판단으로 이어갑니다.</p></section><section class="sp-learning-group"><div class="sp-group-heading"><h3>학습</h3><span>배우기 · 설명하기 · 회상하기</span></div><div class="sp-hub-grid"><article class="sp-hub-item"><div class="sp-eyebrow">멘토링</div><h4>원자료와 학습 기록</h4><p>자료 위치와 간단 메모를 먼저 남기고, 필요한 내용은 상세 기록에 이어 씁니다.</p>${mentoring.length?`<p class="sp-hub-note">최근 기록 · ${esc(mentoring[0].title)}</p>`:''}<button class="sp-btn" data-tab="mentoring">멘토링 기록 열기</button></article><article class="sp-hub-item"><div class="sp-eyebrow">회상 · 복습</div><h4>개념과 질문 카드</h4><p>자료를 덮고 핵심 질문에 답합니다. 자주 막히는 질문을 다음 복습으로 연결합니다.</p><p class="sp-hub-note">미완료 질문 ${questions.length}개</p><button class="sp-btn" data-tab="questions">질문과 복습 열기</button></article></div></section><section class="sp-learning-group"><div class="sp-group-heading"><h3>실전</h3><span>분석하기 · 복기하기</span></div><section class="sp-practice-focus"><div><div class="sp-eyebrow">진행 중인 분석 노트</div><h3>${esc(company?.name||'중심 기업을 정해보세요')}</h3><p>${esc(company?.next_action||company?.core_question||'기업 질문을 정하고 직접 확인할 자료를 찾습니다.')}</p></div><button class="sp-btn primary" data-tab="companies">분석 노트 열기</button></section><div class="sp-hub-grid sp-hub-grid-two"><article class="sp-hub-item"><h4>DCF 가정</h4><p>가정의 근거와 결과를 바꾸는 요인을 점검합니다.</p><button class="sp-btn" data-tab="dcf_review">DCF 기록</button></article><article class="sp-hub-item"><h4>내 판단 · 복기</h4><p>당시 근거와 실제 결과를 나누어 돌아봅니다.</p><button class="sp-btn" data-tab="judgment_review">판단 복기</button></article></div><p class="sp-muted sp-hub-foot">최근 실전 기록 ${records.length}개</p></section>`}
function focusView(){const s=state.sessions.find(x=>x.id===state.focusId);if(!s){state.focusId=null;return ''}const company=state.companies.find(c=>c.is_primary&&c.status==='active'),question=state.questions.find(q=>!q.completed_at&&q.due_on<=iso(new Date())),reading=state.inbox.find(i=>i.id===s.details?.linked_inbox_id)||state.inbox.find(i=>!i.processed&&i.source_url),linkedRecord=state.records.find(r=>r.id===s.details?.linked_record_id),draft=readFocusDraft(s.id);let supporting='';if(s.category==='mentoring')supporting=`<section class="sp-focus-resource"><h3>멘토링 자료 위치</h3>${s.details?.source_url?`<a class="sp-btn" href="${esc(s.details.source_url)}" target="_blank" rel="noopener">원자료 열기 ↗</a>`:''}<p>${esc(s.details?.source_location||'원자료의 강의·영상 위치를 메모하거나 원문 링크를 등록하세요.')}</p></section>`;else if(s.category==='recall')supporting=`<section class="sp-focus-resource"><h3>회상 질문</h3><p>${esc(question?.question||s.details?.output||'자료를 보지 않고 오늘 배운 핵심을 설명해 보세요.')}</p></section>`;else if(s.category==='company'){const note=state.records.find(r=>r.record_type==='company_research'&&(!company||!r.details?.company_id||r.details.company_id===company.id));supporting=`<section class="sp-focus-resource"><h3>분석 중인 노트</h3><p>${esc(company?.name||'중심 기업이 지정되지 않았어요.')}</p><p><strong>핵심 질문</strong> ${esc(company?.core_question||s.details?.output||'')}</p><p><strong>다음 확인</strong> ${esc(company?.next_action||company?.change_to_check||'')}</p>${note?`<details><summary>최근 분석 노트 · ${esc(note.title)}</summary>${recordSummary(note)}</details>`:''}${note?'<button class="sp-link" type="button" data-act="open-company-note">최근 분석 노트 펼치기</button>':''}</section>`;}else if(s.category==='inbox'||s.category==='optional'){const sourceUrl=s.details?.source_url||reading?.source_url,sourceTitle=s.details?.linked_inbox_title||reading?.title||s.title,reason=s.details?.reading_reason||reading?.reason,questionText=s.details?.linked_question||reading?.linked_question;supporting=`<section class="sp-focus-resource"><h3>연결한 자료</h3><p>${esc(sourceTitle)}</p>${reason?`<p><strong>저장 이유</strong> ${esc(reason)}</p>`:''}${questionText?`<p><strong>연결 학습·실전 노트</strong> ${esc(questionText)}</p>`:''}${sourceUrl?`<a class="sp-btn" href="${esc(sourceUrl)}" target="_blank" rel="noopener">원문 열기 ↗</a>`:'<p>원문 주소가 없어요. 자료함에서 원문 링크를 추가할 수 있습니다.</p>'}</section>`;}
 return `<section class="sp-focus"><div class="sp-eyebrow">집중 화면 · ${CATEGORIES[s.category]||'공부'}</div><h1>${esc(s.title)}</h1><p class="sp-muted">${s.planned_minutes}분 예정 · 타이머 없이 진행해도 괜찮아요.</p>${s.details?.study_steps?`<section class="sp-focus-resource"><h2>오늘의 공부 순서</h2><p>${esc(s.details.study_steps)}</p></section>`:''}${s.details?.completion_criteria||s.details?.output?`<section class="sp-focus-resource"><h2>완료 기준</h2><p>${esc(s.details.completion_criteria||s.details.output)}</p></section>`:''}${s.next_step?`<p class="sp-first-next"><strong>다음 행동</strong> ${esc(s.next_step)}</p>`:''}${linkedRecord?`<section class="sp-focus-resource"><h2>연결한 원래 노트</h2><p>${esc(linkedRecord.title)}</p><button class="sp-btn sm" type="button" data-act="open-linked-record" data-id="${linkedRecord.id}">이 노트 이어서 작성</button></section>`:s.details?.linked_record_id?`<p class="sp-muted">연결된 기록을 찾을 수 없습니다.</p>`:""}${supporting}<form id="focus-form"><label for="focus-result">${s.category==='recall'?'내 답':'이번 작업 기록'}</label><textarea class="sp-text" id="focus-result" name="actual_result" placeholder="핵심만 짧게 적어도 충분해요">${esc(draft?.actual_result??s.actual_result??'')}</textarea><div class="sp-focus-inline"><label for="focus-next">다음 첫 행동</label><input class="sp-input" id="focus-next" name="next_step" value="${esc(draft?.next_step??s.next_step??'')}" placeholder="예: 다음에는 실적발표에서 마진 변화를 확인"><label for="focus-minutes">실제 공부 시간 (분, 선택)</label><input class="sp-input" id="focus-minutes" name="actual_minutes" type="number" min="0" max="1440" step="5" value="${draft?.actual_minutes??s.actual_minutes??''}" placeholder="분"></div><div class="sp-focus-save"><span id="focus-save-status" role="status">${draft?'임시 저장됨 · 기록 저장을 누르면 계정에 반영됩니다.':state.savedFocus?'저장된 기록을 불러왔어요.':'저장되지 않은 변경이 있어요.'}</span><button class="sp-btn primary" type="submit">기록 저장</button></div></form><details><summary>관련 자료 · 이전 기록</summary><div class="sp-support-body">${s.details?.method?`<p>${esc(s.details.method)}</p>`:''}${s.details?.linked_target?`<p><strong>연결 대상</strong> ${esc(s.details.linked_target)}</p>`:''}${s.actual_result?`<p><strong>이전 기록</strong><br>${esc(s.actual_result)}</p>`:'<p class="sp-muted">이 작업의 이전 기록이 없습니다.</p>'}</div></details><button class="sp-btn primary sp-end" data-act="finish-session" data-id="${s.id}">작업 마치기</button></section>`}
function finishView(){const s=state.sessions.find(x=>x.id===state.finishId);if(!s){state.finishId=null;return ''}return `<section class="sp-finish"><div class="sp-eyebrow">짧은 종료</div><h1>여기까지 기록했어요</h1><p>${esc(s.title)}</p>${s.next_step?`<div class="sp-next-action"><strong>다음 첫 행동</strong><br>${esc(s.next_step)}</div>`:`<label for="finish-next">다음에 이어갈 첫 행동</label><input class="sp-input" id="finish-next" value="" placeholder="예: 자료에서 매출총이익률 표 확인">`}<label class="sp-finish-date-label" for="finish-date">이어갈 날짜 (선택)</label><input class="sp-input sp-finish-date" id="finish-date" type="date" value=""><div class="sp-finish-actions"><button class="sp-btn primary" data-act="complete-session" data-id="${s.id}">오늘 작업 완료</button><button class="sp-btn" data-act="continue-later" data-id="${s.id}">다음에 이어하기</button><button class="sp-btn" data-act="skip-session" data-id="${s.id}">건너뛰기</button></div><details><summary>체화 상태 변경 (선택)</summary><label class="sp-check-row"><input type="checkbox" id="mastered-check" ${s.details?.mastered?'checked':''}> 이 내용을 설명하고 적용할 수 있어요</label></details></section>`}
function weekChart(rows){const totals=Array(7).fill(0);rows.forEach(s=>{const i=(parse(s.session_date).getDay()+6)%7;totals[i]+=s.planned_minutes});const max=Math.max(60,...totals);return totals.map((v,i)=>`<div class="sp-chart-day"><div class="sp-barbox"><div class="sp-bar ${iso(addDays(state.week,i))===iso(new Date())?'today':''}" style="height:${Math.max(v?5:3,v/max*78)}px" title="${v}분"></div></div><span>${'월화수목금토일'[i]}</span></div>`).join('')}
function todayFocus(rows){const d=iso(new Date()),list=rows.filter(s=>s.session_date===d).sort(sortSessions);return list.length?list.map(s=>`<div class="sp-item"><div class="sp-item-head"><div class="sp-item-title">${esc(s.title)}</div><small>${s.planned_minutes}분</small></div><p>${esc(s.details?.output||'')} ${s.status==='done'?'· 완료':''}</p><button class="sp-link" data-act="edit-session" data-id="${s.id}">진행 기록</button></div>`).join(''):'<p class="sp-muted">오늘 일정이 없어요. 미진도를 보충하려고 새 주제를 늘리기보다 복습이나 다음 시작점을 남겨도 좋아요.</p>'}
function sortSessions(a,b){const date=a.session_date.localeCompare(b.session_date);if(date)return date;const ao=a.details?.template_order,bo=b.details?.template_order;if(Number.isFinite(ao)&&Number.isFinite(bo))return ao-bo;return (a.created_at||'').localeCompare(b.created_at||'')}
function empty(title,sub){return `<div class="sp-empty"><strong>${title}</strong>${sub}</div>`}
function sessionGroups(rows){let last='';return rows.map(s=>{const d=s.session_date;const day=d!==last?(last=d,`<div class="sp-day">${dateLabel(d)} · ${DAY_NAMES[parse(d).getDay()]}</div>`):'';return `${day}${sessionCard(s)}`}).join('')}
function sessionCard(s){return `<div class="sp-task ${s.status==='done'?'done':''}"><input type="checkbox" data-act="toggle-session" data-id="${s.id}" ${s.status==='done'?'checked':''} aria-label="완료"><div><div class="sp-task-title">${esc(s.title)}</div><div class="sp-task-meta"><span class="sp-pill">${CATEGORIES[s.category]}</span> ${s.planned_minutes}분 예정${s.actual_minutes?` · ${s.actual_minutes}분 실제`:''} · ${s.status==='done'?'완료':s.status==='partial'?'일부 진행':s.status==='skipped'?'건너뜀':'예정'}</div>${s.details?.output?`<div class="sp-task-meta">남길 결과: ${esc(s.details.output)}</div>`:''}${s.actual_result?`<div class="sp-task-result"><strong>실제:</strong> ${esc(s.actual_result)}</div>`:''}${s.next_step?`<div class="sp-task-meta"><strong>다음:</strong> ${esc(s.next_step)}</div>`:''}</div><div class="sp-task-actions"><button class="sp-link" data-act="edit-session" data-id="${s.id}">수정</button><button class="sp-link" data-act="delete-session" data-id="${s.id}">삭제</button></div></div>`}
function plan(){const rows=weekSessions().slice().sort(sortSessions),today=iso(new Date()),missed=rows.filter(s=>s.session_date<today&&s.status==='planned');return `<section class="sp-card"><div class="sp-card-head"><div><h2>주간 시간표</h2><p>요일·순서·시간을 수정하고 필요하면 일정을 재배정합니다.</p></div><div class="sp-row-actions"><button class="sp-btn sm" data-tab="weekly_plan">주간 점검</button><button class="sp-btn sm" data-tab="trial_review">2주 점검</button><button class="sp-btn sm" data-act="seed-week">기본 시간표 ${rows.length?'다시 만들기':'만들기'}</button><button class="sp-btn primary sm" data-act="add-session">＋ 일정 추가</button></div></div><div class="sp-toolbar"><span class="sp-muted">각 일정의 수정에서 날짜·순서·예정 시간을 바꿀 수 있어요.</span></div>${missed.length?`<section class="sp-missed"><h3>지난 날짜에 남은 작업</h3>${missed.map(s=>`<div class="sp-next-row"><strong>${esc(s.title)}</strong><span>${dateLabel(s.session_date)}</span><div class="sp-row-actions"><button class="sp-btn sm" data-act="edit-session" data-id="${s.id}">재배정</button><button class="sp-btn sm" data-act="week-exclude" data-id="${s.id}">이번 주 제외</button><button class="sp-btn sm" data-act="leave-missed" data-id="${s.id}">그대로 두기</button></div></div>`).join('')}</section>`:''}<div class="sp-list">${rows.length?sessionGroups(rows):empty('선택한 주에 일정이 없어요','기본 시간표 만들기로 계획을 생성하세요.')}</div></section><section class="sp-help" style="margin-top:12px"><strong>추가 시간:</strong> 평일 선택형 보충 블록은 최대 30분입니다. 놓친 작업은 자동으로 다음 날에 옮기지 않아요.</section>`}
function questionsView(){const ws=iso(state.week),list=state.questions.filter(q=>q.week_start===ws).sort((a,b)=>a.due_on.localeCompare(b.due_on)),due=state.questions.filter(q=>!q.completed_at&&q.due_on<=iso(new Date()));return `<section class="sp-grid"><article class="sp-card"><div class="sp-card-head"><div><h2>핵심 복습 질문</h2><p>이번 주 최대 3개 · 멘토링 / 기업 / 매크로에서 하나씩</p></div><button class="sp-btn primary sm" data-act="add-question" ${list.length>=3?'disabled':''}>＋ 질문 추가 ${list.length}/3</button></div><div class="sp-card-body">${list.length?list.map(questionCard).join(''):empty('이번 주 질문을 최대 3개 정해보세요','정답 암기보다 판단에 필요한 논리를 설명하는 질문을 고릅니다.')}</div></article><aside class="sp-card"><div class="sp-card-head"><div><h2>간격 복습 순서</h2><p>자료를 덮고 먼저 답해요</p></div></div><div class="sp-card-body"><div class="sp-item">당일 · 자료 없이 설명</div><div class="sp-item">다음 공부일 · 질문만 보고 다시 답하기</div><div class="sp-item">다음 주말 · 다른 사례에 적용</div><div class="sp-item">약 4주 뒤 · 반례와 성립 조건까지 설명</div><p class="sp-muted">이미 설명할 수 있는 질문은 복습량을 줄이고, 반복해 막히는 질문에 시간을 씁니다. 오늘 복습 예정 ${due.length}개.</p></div></aside></section>`}
function questionCard(q){const stage=['당일 회상','다음 공부일','다음 주말','약 4주 뒤'][q.review_stage]||'복습 완료';return `<article class="sp-item"><div class="sp-item-head"><div><span class="sp-pill">${AREAS[q.area]}</span><span class="sp-item-title"> ${esc(q.question)}</span></div><div class="sp-row-actions"><button class="sp-link" data-act="review-question" data-id="${q.id}">회상 기록</button><button class="sp-link" data-act="delete-question" data-id="${q.id}">삭제</button></div></div><p><small>${stage} · 예정 ${dateLabel(q.due_on)}${q.completed_at?' · 완료':''}</small></p>${q.last_answer?`<p><strong>내 답:</strong> ${esc(q.last_answer)}</p>`:''}</article>`}
function inboxView(){const pending=state.inbox.filter(i=>!i.processed),processed=state.inbox.filter(i=>i.processed),counts=pending.reduce((a,x)=>(a[x.queue]=(a[x.queue]||0)+1,a),{});return `<section class="sp-grid"><article class="sp-card"><div class="sp-card-head"><div><h2>자료함</h2><p>원문과 저장 이유를 보관하고, 필요한 자료만 공부할 작업과 날짜에 연결합니다.</p></div><button class="sp-btn primary sm" data-act="add-inbox" ${pending.length>=5?'disabled':''}>＋ 자료 저장</button></div><div class="sp-toolbar"><span class="sp-pill">지금 확인 ${counts.now||0}</span><span class="sp-pill">이번 주 읽기 ${counts.this_week||0}</span><span class="sp-pill">참고 보관 ${counts.reference||0}</span><span class="sp-pill">지나가기 ${counts.skip||0}</span></div><div class="sp-card-body">${pending.map(inboxCard).join('')||empty('미처리 자료가 없습니다','좋은 자료를 발견해도 이번 주 질문에 연결되는지 먼저 살펴보세요.')}${processed.length?`<details><summary class="sp-muted">처리한 자료 ${processed.length}개 보기</summary>${processed.map(inboxCard).join('')}</details>`:''}</div></article><aside class="sp-card"><div class="sp-card-head"><div><h2>저장 기준</h2><p>현재 질문에 답하기 위한 자료만</p></div></div><div class="sp-card-body"><div class="sp-item"><strong>지금 확인</strong><p>보유·분석 기업의 중요한 새 사실 → 관련 공부 시간에 우선 검토</p></div><div class="sp-item"><strong>이번 주 읽기</strong><p>이번 주 질문에 직접 답하는 자료 → 예정된 블록에서 읽기</p></div><div class="sp-item"><strong>참고 보관 / 지나가기</strong><p>유용하지만 현재와 무관하면 이유만 남겨 보관. 중복·목적 불명은 저장하지 않기.</p></div><p class="sp-muted">링크를 저장할 때 제목, 출처, 연결 질문, 저장 이유, 다음 행동만 남기세요.</p></div></aside></section>`}
function inboxCard(i){return `<article class="sp-item"><div class="sp-item-head"><div><div class="sp-item-title">${esc(i.title)}</div><small>${esc(i.source||'')} · ${dateLabel(i.saved_on,false)} · ${i.processed?'보관 완료':i.queue==='now'?'지금 확인':i.queue==='this_week'?'이번 주 읽기':i.queue==='reference'?'참고 보관':'지나가기'}</small></div><div class="sp-library-actions"><button class="sp-link" data-act="edit-inbox" data-id="${i.id}">수정</button><button class="sp-link" data-act="process-inbox" data-id="${i.id}">${i.processed?'되돌리기':'처리'}</button><button class="sp-link" data-act="delete-inbox" data-id="${i.id}">삭제</button></div></div>${i.source_url?`<p><a href="${esc(i.source_url)}" target="_blank" rel="noopener">원문 열기 ↗</a></p>`:''}${i.linked_question?`<p><strong>연결 학습·실전 노트:</strong> ${esc(i.linked_question)}</p>`:''}${i.reason?`<p><strong>저장 이유:</strong> ${esc(i.reason)}</p>`:''}${i.note?`<p>${esc(i.note)}</p>`:''}<button class="sp-btn sm" data-act="schedule-inbox" data-id="${i.id}">이 자료로 공부 일정 만들기</button></article>`}
function companiesView(){const active=state.companies.filter(c=>c.status==='active'),others=state.companies.filter(c=>c.status!=='active');return `<section class="sp-card"><div class="sp-card-head"><div><h2>기업 분석 프로젝트</h2><p>후보는 보관하되 한 번에 한 기업을 중심으로 진행합니다. 끝나지 않으면 4주를 넘겨 이어가세요.</p></div><button class="sp-btn primary sm" data-act="add-company">＋ 기업 후보</button></div><div class="sp-card-body"><div class="sp-help"><strong>4주 진행 가이드:</strong> 1주차 사업 구조·핵심 변수 → 2주차 실적 변화·반대 근거 → 3주차 근거 기반 학습용 DCF → 4주차 틀릴 조건·시나리오 수정·최종 메모. 각 주차 단계는 연장할 수 있습니다.</div><div class="sp-company-grid" style="margin-top:12px">${active.map(companyCard).join('')||empty('중심 분석 기업을 지정해 주세요','새 후보를 등록하고 관심 이유와 확인 질문을 적은 뒤 중심 기업으로 지정하세요.')}${others.map(companyCard).join('')}</div></div></section><section class="sp-grid" style="margin-top:14px"><article class="sp-card"><div class="sp-card-head"><div><h2>기업 연구 기록</h2><p>사업·실적·현금흐름·반대 근거를 한 흐름에 누적</p></div><button class="sp-btn sm" data-act="new-record" data-type="company_research">＋ 기록</button></div><div class="sp-card-body">${recentRecords('company_research')}</div></article><aside class="sp-card"><div class="sp-card-head"><div><h2>분석에 포함할 연습</h2></div></div><div class="sp-card-body"><p class="sp-muted">재무제표와 현금흐름 연결 · 사실/경영진 전망/타인 추정/내 가정 분리 · 반대 근거 찾기 · 매크로 영향 가설 · 이전 판단과 실제 비교</p><p class="sp-muted">막히는 재무 개념은 현재 기업에서 필요한 만큼 공부하고 바로 적용하세요.</p></div></aside></section>`}
function companyCard(c){const stages=['사업 구조','실적 변화','학습용 DCF','반대 근거·최종 메모'];return `<article class="sp-company ${c.is_primary?'focus':''}"><div class="sp-item-head"><div><div class="sp-item-title">${esc(c.name)} ${c.is_primary?'· 중심':''}</div><small>${c.status==='active'?'분석 진행 중':c.status==='candidate'?'후보 보관':c.status==='paused'?'보류':'완료'} ${c.started_on?`· 시작 ${dateLabel(c.started_on,false)}`:''}</small></div><button class="sp-link" data-act="edit-company" data-id="${c.id}">수정</button></div>${c.status==='active'?`<div class="sp-stage">${stages.map((_,i)=>`<span class="${i<c.project_week?'on':''}"></span>`).join('')}</div><label class="sp-muted">현재 ${c.project_week}주차</label><select class="sp-select" data-act="company-stage" data-id="${c.id}">${stages.map((s,i)=>`<option value="${i+1}" ${c.project_week===i+1?'selected':''}>${i+1}주차 · ${s}</option>`).join('')}</select>`:''}${c.reason?`<p><strong>관심 이유:</strong> ${esc(c.reason)}</p>`:''}${c.core_question?`<p><strong>핵심 질문:</strong> ${esc(c.core_question)}</p>`:''}${c.next_action?`<p><strong>다음 행동:</strong> ${esc(c.next_action)}</p>`:''}<div class="sp-row-actions" style="margin-top:8px">${!c.is_primary&&c.status!=='done'?`<button class="sp-btn sm" data-act="focus-company" data-id="${c.id}">중심 기업 지정</button>`:''}<button class="sp-btn sm" data-act="new-record" data-type="company_research" data-company="${c.id}">분석 기록</button><button class="sp-btn sm" data-act="new-record" data-type="dcf_review" data-company="${c.id}">DCF 가정</button></div></article>`}
function recordView(type){const fields=RECORD_FIELDS[type]||[];return `<section class="sp-grid"><article class="sp-card"><div class="sp-card-head"><div><h2>${RECORD_TITLES[type]||'공부 기록'}</h2><p>${recordSub(type)}</p></div><button class="sp-btn primary sm" data-act="new-record" data-type="${type}">＋ 새 기록</button></div><div class="sp-card-body">${recentRecords(type)}</div></article><aside class="sp-card"><div class="sp-card-head"><div><h2>운영 기준</h2></div></div><div class="sp-card-body">${recordHelp(type)}</div></aside></section>`}
function recordSub(t){return ({weekly_plan:'멘토링 진도·기업 질문·주요 일정·선택 자료·다음 첫 행동을 이번 주 기준으로 정리합니다',mentoring:'수강 → 회상 → 적용 · 영상을 끝낸 것이 아니라 핵심 논리를 설명하는 것이 완료 기준',weekly_review:'지난주 판단을 유지·수정·보류하고 다음 확인 시점을 남깁니다',dcf_review:'적정주가보다 중요한 가정과 불확실성을 설명하는 연습',judgment_review:'결과의 좋고 나쁨과 판단 과정의 질을 별도로 평가합니다',trial_review:'첫 2주는 계획이 생활에 맞는지 확인하고 필수 분량을 조정합니다'})[t]||''}
function recordHelp(t){const texts={weekly_plan:'한 주의 큰 방향만 정리하고, 매일의 공부 블록은 시간표에서 관리합니다. 멘토링 진도와 목표, 집중 기업과 질문, 확인 일정, 선택해서 읽을 자료, 다음 시작 행동을 기록하세요. 핵심 복습 질문은 별도 탭에서 최대 3개 관리합니다.',mentoring:'<strong>보기 전</strong> 지난 질문을 떠올리고 이번에 알고 싶은 것을 정합니다.<br><br><strong>보는 중</strong> 주장·근거·성립 조건·모르는 부분만 표시합니다.<br><br><strong>본 후</strong> 화면을 닫고 내 말로 설명한 뒤 기업·매크로에 적용할 질문을 남깁니다.',weekly_review:'성장·물가·정책·금융환경·기업 연결은 고정된 틀로 확인합니다. 발표일과 관측 기간, 실제값·예상·이전값·수정 여부를 구분하세요. 가격 반응만으로 매수 주체나 원인을 단정하지 않습니다.',dcf_review:'완성 예제 이해 → 일부 가정 직접 작성 → 가정 변화의 영향 설명 → 독립 분석. 매출·수익성·투자·현금흐름·할인율·장기 가정을 기록하고 단위·기준일·주식수·순차입금을 확인합니다.',judgment_review:'당시 정보로 판단 과정을 평가하고 실제 결과와 비교합니다. 좋은 결과가 좋은 분석을 뜻하지도, 나쁜 결과가 나쁜 과정을 뜻하지도 않습니다.',trial_review:'멘토링 진도·회상·기업 근거·주간 판단·자료 수신함·지속 가능성을 확인합니다. 잘 안 되면 양식을 늘리지 말고 필수 분량을 줄입니다.'};return `<div class="sp-help">${texts[t]||''}</div>${t==='mentoring'?`<h3>내 답을 먼저 쓴 뒤 AI에 검증 요청</h3><div class="sp-prompt" id="ai-prompt">아래는 자료를 보지 않고 내가 설명한 내용이다. 정답부터 쓰지 말고 사실 오류, 빠진 인과관계, 근거 없는 가정, 반대 사례를 구분해줘. 가장 중요한 빈틈부터 질문해줘.</div><button class="sp-btn sm" data-act="copy-prompt">문구 복사</button>`:''}${t==='weekly_review'?`<h3>주간 판단 문장</h3><div class="sp-prompt">지난주에는 ○○라고 봤다. 이번 주 ○○를 확인해서 유지·수정·보류한다. 다음에는 ○○를 확인한다.</div>`:''}${t==='company_research'?`<div class="sp-prompt">AI 검증: 경쟁하는 설명을 제시하고, 어떤 자료로 두 설명을 구분하는지 알려줘. 확인된 사실과 추론은 분리해줘.</div>`:''}`}
function recentRecords(type){const rows=state.records.filter(r=>r.record_type===type).slice(0,30);return rows.length?rows.map(r=>`<article class="sp-item"><div class="sp-item-head"><div><div class="sp-item-title">${esc(r.title)}</div><small>${dateLabel(r.record_date,false)}${r.week_start?` · 주 ${dateLabel(r.week_start,false)}`:''}</small></div><div><button class="sp-link" data-act="edit-record" data-id="${r.id}">수정</button><button class="sp-link" data-act="delete-record" data-id="${r.id}">삭제</button></div></div>${recordSummary(r)}</article>`).join(''):empty('아직 저장한 기록이 없어요','새 기록을 작성하면 이 공간에 쌓입니다.')}
function recordSummary(r){const d=r.details||{};const important=Object.entries(d).filter(([k,v])=>v&&typeof v==='string'&&k!=='company_id').slice(0,4);return important.map(([k,v])=>`<p><strong>${esc(fieldLabel(r.record_type,k))}:</strong> ${esc(v.slice(0,300))}${v.length>300?'…':''}</p>`).join('')}
function fieldLabel(type,key){return (RECORD_FIELDS[type]||[]).find(x=>x[0]===key)?.[1]||key}

function modalHtml(){const m=state.modal,body=m.kind==='schedule-preview'?schedulePreviewHtml():m.kind==='move-date'?`<form id="modal-form" data-kind="move-date"><label for="move-date-input">옮길 날짜</label><input id="move-date-input" class="sp-input" type="date" name="session_date" required value="${esc(m.row.session_date)}"><p class="sp-muted">기존 기록과 세부 내용은 그대로 두고 날짜만 변경합니다.</p></form>`:m.kind==='session'?sessionForm(m.row):m.kind==='question'?questionForm(m.row):m.kind==='question-review'?questionFormReview(m.row):m.kind==='inbox'?inboxForm(m.row):m.kind==='company'?companyForm(m.row):m.kind==='password'?passwordChangeForm():recordForm(m.type,m.row),actions=m.kind==='question-review'||m.kind==='schedule-preview'||m.kind==='password'?'':`<div class="sp-modal-actions"><button class="sp-btn" data-act="cancel">취소</button><button class="sp-btn primary" data-act="save-modal">${m.kind==='move-date'?'이동':'저장'}</button></div>`;return `<div class="sp-modal-bg" data-act="backdrop"><section class="sp-modal ${m.kind==='schedule-preview'?'sp-modal-schedule':''}"><h2>${esc(m.title)}</h2>${body}${actions}</section></div>`}
function passwordChangeForm(){return `<form id="password-change-form"><div class="sp-fields"><div class="sp-field full"><label>새 비밀번호 (8자 이상)</label><input class="sp-input" type="password" name="password" autocomplete="new-password" minlength="8" required></div><div class="sp-field full"><label>새 비밀번호 확인</label><input class="sp-input" type="password" name="confirmPassword" autocomplete="new-password" minlength="8" required></div></div><div class="sp-modal-actions"><button class="sp-btn" type="button" data-act="cancel">취소</button><button class="sp-btn primary" type="submit">비밀번호 저장</button></div><div class="sp-errors" id="password-change-error"></div></form>`}
function fieldHtml([key,label,type,placeholder],value='',row={}){if(type==='company'){return `<div class="sp-field"><label>${label}</label><select class="sp-select" name="${key}"><option value="">선택 안 함</option>${state.companies.map(c=>`<option value="${c.id}" ${(row.company_id||'')===c.id?'selected':''}>${esc(c.name)}${c.is_primary?' · 중심':''}</option>`).join('')}</select></div>`}if(type==='select'){const opts=placeholder.split('|');return `<div class="sp-field"><label>${label}</label><select class="sp-select" name="${key}">${opts.map(o=>`<option value="${o}" ${value===o?'selected':''}>${o}</option>`).join('')}</select></div>`}if(type==='date')return `<div class="sp-field"><label>${label}</label><input class="sp-input" type="date" name="${key}" value="${esc(value||iso(new Date()))}"></div>`;const area=type==='textarea';return `<div class="sp-field ${area?'full':''}"><label>${label}</label>${area?`<textarea class="sp-text" name="${key}" placeholder="${esc(placeholder)}">${esc(value||'')}</textarea>`:`<input class="sp-input" name="${key}" value="${esc(value||'')}" placeholder="${esc(placeholder)}">`}</div>`}
function sessionForm(r={}){const d=r.details||{};return `<form id="modal-form" data-kind="session"><div class="sp-fields"><div class="sp-field"><label>날짜</label><input class="sp-input" type="date" name="session_date" required value="${esc(r.session_date||state.viewDate||iso(new Date()))}"></div><div class="sp-field"><label>공부 영역</label><select class="sp-select" name="category">${Object.entries(CATEGORIES).map(([k,v])=>`<option value="${k}" ${r.category===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="sp-field"><label>예정 시간 (분)</label><input class="sp-input" type="number" name="planned_minutes" min="5" max="1440" step="5" value="${r.planned_minutes||30}" required></div><div class="sp-field full"><label>공부할 내용</label><input class="sp-input" name="title" required value="${esc(r.title||'')}" placeholder="핵심 질문 또는 공부 행동"></div></div><details class="sp-detail-fields"><summary>상세 펼치기</summary><div class="sp-fields"><div class="sp-field full"><label>연결할 기존 학습·실전 기록 (선택)</label><select class="sp-select" name="linked_record_id"><option value="">연결하지 않음 / 일정 안에서 진행</option>${state.records.map(x=>`<option value="${x.id}" ${d.linked_record_id===x.id?'selected':''}>${esc(x.title||RECORD_TITLES[x.record_type]||'기록')} · ${esc(RECORD_TITLES[x.record_type]||x.record_type)}</option>`).join('')}</select></div><div class="sp-field full"><label>연결할 자료함 항목 (선택)</label><select class="sp-select" name="linked_inbox_id"><option value="">자료 연결 안 함</option>${state.inbox.map(x=>`<option value="${x.id}" ${d.linked_inbox_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="sp-field full"><label>공부 순서</label><textarea class="sp-text" name="study_steps">${esc(d.study_steps||d.method||'')}</textarea></div><div class="sp-field full"><label>완료 기준</label><textarea class="sp-text" name="completion_criteria">${esc(d.completion_criteria||d.output||'')}</textarea></div><div class="sp-field full"><label>연결 대상 / 원자료 위치</label><input class="sp-input" name="linked_target" value="${esc(d.linked_target||d.source_location||'')}"></div><div class="sp-field full"><label>원자료 링크</label><input class="sp-input" type="url" name="source_url" value="${esc(d.source_url||'')}" placeholder="외부 강의·글의 원문 주소"></div><div class="sp-field full"><label>진행 메모</label><textarea class="sp-text" name="method" placeholder="참고할 방법이나 세부사항">${esc(d.method||'')}</textarea></div><div class="sp-field"><label>실제 공부 시간 (분, 선택)</label><input class="sp-input" type="number" name="actual_minutes" min="0" max="1440" step="5" value="${r.actual_minutes||''}" placeholder="예: 35"></div><div class="sp-field"><label>추가 메모</label><input class="sp-input" name="output" value="${esc(d.output||'')}"></div></div></details></form>`}
function questionForm(r={}){return `<form id="modal-form" data-kind="question"><div class="sp-fields"><div class="sp-field"><label>영역</label><select class="sp-select" name="area">${Object.entries(AREAS).map(([k,v])=>`<option value="${k}" ${r.area===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="sp-field"><label>복습 예정</label><input class="sp-input" type="date" name="due_on" value="${esc(r.due_on||iso(new Date()))}"></div><div class="sp-field full"><label>이번 주 핵심 질문</label><textarea class="sp-text" name="question" required placeholder="판단에 필요한 논리를 설명할 수 있는 질문">${esc(r.question||'')}</textarea></div></div></form>`}
function inboxForm(r={}){return `<form id="modal-form" data-kind="inbox"><div class="sp-fields"><div class="sp-field full"><label>자료 제목</label><input class="sp-input" name="title" required value="${esc(r.title||'')}"></div><div class="sp-field"><label>출처</label><input class="sp-input" name="source" value="${esc(r.source||'')}"></div><div class="sp-field"><label>자료 링크</label><input class="sp-input" type="url" name="source_url" value="${esc(r.source_url||'')}"></div><div class="sp-field"><label>분류</label><select class="sp-select" name="queue">${[['now','지금 확인'],['this_week','이번 주 읽기'],['reference','참고 보관'],['skip','지나가기']].map(([k,v])=>`<option value="${k}" ${r.queue===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="sp-field"><label>다음 행동</label><select class="sp-select" name="next_action">${[['read','읽기'],['check','확인하기'],['link','기존 기록 연결'],['archive','보관'],['discard','삭제 예정']].map(([k,v])=>`<option value="${k}" ${r.next_action===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="sp-field full"><label>연결할 학습·실전 질문 / 노트 (선택)</label><input class="sp-input" name="linked_question" value="${esc(r.linked_question||'')}" placeholder="예: 기업명 · 이번 주 핵심 질문"></div><div class="sp-field full"><label>저장 이유</label><textarea class="sp-text" name="reason" placeholder="내 가정을 강화·약화하거나 답할 질문과 연결">${esc(r.reason||'')}</textarea></div><div class="sp-field full"><label>짧은 메모 (선택)</label><textarea class="sp-text" name="note">${esc(r.note||'')}</textarea></div></div></form>`}
function companyForm(r={}){return `<form id="modal-form" data-kind="company"><div class="sp-fields"><div class="sp-field"><label>기업명</label><input class="sp-input" name="name" required value="${esc(r.name||'')}"></div><div class="sp-field"><label>상태</label><select class="sp-select" name="status">${[['candidate','후보'],['active','분석 진행'],['paused','보류'],['done','완료']].map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="sp-field full"><label>관심을 가진 이유</label><textarea class="sp-text" name="reason">${esc(r.reason||'')}</textarea></div><div class="sp-field full"><label>확인하려는 변화</label><textarea class="sp-text" name="change_to_check">${esc(r.change_to_check||'')}</textarea></div><div class="sp-field full"><label>핵심 질문</label><textarea class="sp-text" name="core_question">${esc(r.core_question||'')}</textarea></div><div class="sp-field full"><label>검증할 자료</label><textarea class="sp-text" name="verification_materials">${esc(r.verification_materials||'')}</textarea></div><div class="sp-field"><label>프로젝트 주차</label><select class="sp-select" name="project_week">${[1,2,3,4].map(n=>`<option value="${n}" ${Number(r.project_week||1)===n?'selected':''}>${n}주차</option>`).join('')}</select></div><div class="sp-field"><label>분석 시작일 (후보면 비워두세요)</label><input class="sp-input" type="date" name="started_on" value="${esc(r.started_on||'')}"></div><div class="sp-field full"><label>다음 행동</label><input class="sp-input" name="next_action" value="${esc(r.next_action||'')}"></div></div></form>`}
function recordForm(type,r={}){const d=r.details||{},fields=RECORD_FIELDS[type]||[];return `<form id="modal-form" data-kind="record" data-type="${type}"><div class="sp-fields"><div class="sp-field"><label>기록일</label><input class="sp-input" type="date" name="record_date" value="${esc(r.record_date||iso(new Date()))}"></div><div class="sp-field"><label>제목</label><input class="sp-input" name="title" required value="${esc(r.title||'')}" placeholder="기록을 구분할 짧은 제목"></div>${fields.slice(0,1).map(f=>fieldHtml(f,d[f[0]],d)).join('')}</div>${fields.length>1?`<details class="sp-detail-fields"><summary>상세 펼치기</summary><div class="sp-fields">${fields.slice(1).map(f=>fieldHtml(f,d[f[0]],d)).join('')}</div></details>`:''}</form>`}

